import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import { readCloudData, writeCloudSection } from "./cloudStore";

type FinanceView = "dashboard" | "accounts" | "transactions" | "cards" | "cashflow" | "projections" | "reports" | "settings";
type AccountType = "Banco" | "Carteira" | "Caixa" | "Investimento" | "Cartão";
type Account = { id: string; name: string; bank: string; type: AccountType; balance: number; limit: number; closingDay?: number; dueDay?: number; active?: boolean };
type Entry = { id: string; kind: "income" | "expense"; description: string; bankDescription?: string; paymentMethod?: string; amount: number; additionalAmount?: number; additionalDescription?: string; discountAmount?: number; category: string; accountId: string; competenceDate: string; dueDate: string; paymentDate?: string; status: string; recurring: boolean; installments: number; isCreditCard: boolean; attachment?: string; projected?: boolean };

let settleFinanceEntry: ((entry: Entry) => void) | undefined;
let requestFinanceSettlement: ((entries: Entry[]) => void) | undefined;
let requestEntryDetails: ((entry: Entry) => void) | undefined;
let deleteFinanceEntries: ((entries: Entry[]) => void) | undefined;
const money = (value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);
const shortDate = (value: string) => value ? new Intl.DateTimeFormat("pt-BR", { timeZone: "UTC" }).format(new Date(`${value}T00:00:00Z`)) : "—";
const inputMoney = (value: string) => { const number = Number(value.replace(/\./g, "").replace(",", ".")); return Number.isFinite(number) && value ? new Intl.NumberFormat("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(number) : ""; };
const parseMoney = (value: string) => Number(value.replace(/\./g, "").replace(",", "."));
const addMonths = (date: string, months: number) => {
  const [year, month, day] = date.split("-").map(Number);
  const next = new Date(Date.UTC(year, month - 1 + months, Math.min(day, 28)));
  return next.toISOString().slice(0, 10);
};
const expandInstallments = (entry: Entry) => entry.installments <= 1 ? [entry] : Array.from({ length: entry.installments }, (_, index) => ({
  ...entry,
  id: crypto.randomUUID(),
  description: `${entry.description} (${index + 1}/${entry.installments})`,
  amount: entry.amount / entry.installments,
  dueDate: addMonths(entry.dueDate, index),
}));

function Icon({ children }: { children: ReactNode }) { return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{children}</svg>; }
